<#
================================================================================
  Animal Crossing Save-Sync + Sperre (Git) - mit grafischer Oberflaeche
================================================================================

  Was macht das Skript?
  ---------------------
  Es startet Dolphin NICHT direkt, sondern kuemmert sich drumherum:
    1. Vor dem Spielen:  holt den neuesten Spielstand aus dem Git-Repo
    2. Setzt eine "Sperre" (PLAYING.lock) mit deinem Namen + Zeitstempel
    3. Waehrend des Spielens: sendet regelmaessig einen "Herzschlag"
       (aktualisiert den Zeitstempel + sichert den Spielstand)
    4. Nach dem Beenden: laedt den Spielstand hoch und gibt die Sperre frei

  Warum kann die Sperre NICHT dauerhaft haengen bleiben?
  ------------------------------------------------------
    - Lease/Ablauf:  Ist der Zeitstempel aelter als "LeaseMinutes" (Standard 5),
      gilt die Sperre als tot und wird automatisch uebernommen. Ein Absturz
      stoppt den Herzschlag -> Sperre laeuft von allein ab.
    - Aufraeumen:  Beendet sich Dolphin normal, wird die Sperre sofort freigegeben.
    - Notausgang:  Der Knopf "Sperre erzwingen freigeben" loescht sie sofort.
    - Beim Schliessen des Fensters wirst du gewarnt; selbst dann laeuft die
      Sperre spaetestens nach LeaseMinutes ab.

  Voraussetzungen (einmalig):
  ---------------------------
    - Git muss installiert und im PATH sein  (git --version testen)
    - Ihr habt EIN gemeinsames privates Git-Repo (z. B. GitHub) und BEIDE
      habt es lokal geklont. RepoPath zeigt auf diesen Ordner.
    - Der Dolphin-Spielstand liegt in diesem Repo-Ordner (oder ihr verlinkt
      den Dolphin-Save-Ordner per Symlink dort hinein).
    - Eure Git-Zugangsdaten sind gespeichert (Git Credential Manager bei HTTPS
      oder ein SSH-Key), sonst kann das Skript nicht ohne Nachfrage pushen.
    - Beide benutzen dieses Skript, ABER mit UNTERSCHIEDLICHEM Spielernamen.

  Starten:
  --------
    Rechtsklick auf die Datei -> "Mit PowerShell ausfuehren"
    Oder in PowerShell:   powershell -ExecutionPolicy Bypass -File .\AC-SaveSync.ps1
================================================================================
#>

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# Git darf NIE in der Konsole nach Benutzername/Passwort fragen: das Programm
# startet ohne sichtbare Konsole, die Frage waere unsichtbar und Git wuerde
# ewig warten. Mit 0 bricht Git stattdessen mit einer Meldung ab - und die
# uebersetzt Write-GitProblem weiter unten in Klartext.
# Der Windows-Anmelde-Dialog (Credential Manager) erscheint weiterhin normal.
$env:GIT_TERMINAL_PROMPT = '0'

# --------------------------------------------------------------------------
# Kurzhilfen (Tooltips), die beim Ueberfahren mit der Maus erscheinen
# --------------------------------------------------------------------------
# EIN ToolTip-Bauteil reicht fuer alle Fenster; es merkt sich pro Control
# einen Text. Wird weiter unten mit Set-Tip befuellt.
$script:tips = New-Object Windows.Forms.ToolTip
$script:tips.InitialDelay = 350       # ms, bis der Hinweis aufgeht
$script:tips.ReshowDelay = 120        # ms beim Wechsel zum naechsten Feld
$script:tips.AutoPopDelay = 30000     # ms, so lange bleibt er stehen
$script:tips.ShowAlways = $true       # auch wenn das Fenster nicht aktiv ist

# Haengt denselben Hinweis an mehrere Controls (Beschriftung + Feld + Knopf),
# damit es egal ist, worueber die Maus steht.
function Set-Tip {
    param(
        [string]$Text,
        [Parameter(ValueFromRemainingArguments = $true)]$Controls
    )
    foreach ($c in $Controls) {
        if ($c) { $script:tips.SetToolTip($c, $Text) }
    }
}

# Eingebettetes Programm-Icon (Base64-ICO, selbst gezeichnetes Blatt-Motiv,
# erzeugt von tools/New-Icon.ps1). Es dient dem Fenster, der Taskleiste und
# der Desktop-Verknuepfung.
# Hinweis: Eine .cmd-Datei selbst kann KEIN Icon tragen - das legt Windows
# ueber die Dateizuordnung fest. Deshalb der Weg ueber die Verknuepfung.
$script:IconBase64 = ""

# Baut das Icon aus dem eingebetteten Text und legt es zusaetzlich als Datei
# ab - eine Verknuepfung braucht einen Pfad, keinen Speicherinhalt.
function Get-AppIcon {
    if ($script:appIcon) { return $script:appIcon }
    try {
        $bytes = [Convert]::FromBase64String($script:IconBase64)
        $script:IconPath = Join-Path $script:AppDir 'ac-savesync.ico'
        [IO.File]::WriteAllBytes($script:IconPath, $bytes)
        $ms = New-Object IO.MemoryStream(, $bytes)
        $script:appIcon = New-Object Drawing.Icon($ms)
    }
    catch {
        $script:appIcon = $null
    }
    return $script:appIcon
}

# Legt eine Verknuepfung auf dem Desktop an - mit Icon, denn die .cmd selbst
# kann keins haben. Rueckgabe: Pfad der Verknuepfung oder "" bei Fehler.
function New-DesktopShortcut {
    try {
        [void](Get-AppIcon)
        $selbst = $script:SelfPath
        if ([string]::IsNullOrWhiteSpace($selbst) -or -not (Test-Path -LiteralPath $selbst)) {
            Write-Log "Verknuepfung nicht moeglich: der eigene Pfad ist unbekannt."
            return ""
        }
        $ziel = Join-Path ([Environment]::GetFolderPath('Desktop')) 'Animal Crossing Save-Sync.lnk'
        $ws = New-Object -ComObject WScript.Shell
        $lnk = $ws.CreateShortcut($ziel)

        if ([IO.Path]::GetExtension($selbst).ToLowerInvariant() -eq '.ps1') {
            # Direkt gestartete .ps1: ueber powershell.exe, sonst oeffnet der Editor
            $lnk.TargetPath = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
            $lnk.Arguments = ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}"' -f $selbst)
        }
        else {
            $lnk.TargetPath = $selbst
        }
        $lnk.WorkingDirectory = Split-Path -Parent $selbst
        $lnk.Description = "Animal Crossing Save-Sync + Sperre"
        if ($script:IconPath -and (Test-Path -LiteralPath $script:IconPath)) {
            $lnk.IconLocation = "$($script:IconPath),0"
        }
        $lnk.Save()
        Write-Log "Verknuepfung auf dem Desktop angelegt."
        return $ziel
    }
    catch {
        Write-Log "Verknuepfung konnte nicht angelegt werden: $($_.Exception.Message)"
        return ""
    }
}

# Eingebettetes Deko-Banner (Base64-PNG, 192x64)
$script:BannerBase64 = ""

# Git soll nie interaktiv nach Passwoertern fragen (sonst haengt das Skript):
$env:GIT_TERMINAL_PROMPT = "0"

# --------------------------------------------------------------------------
# Konfiguration
# --------------------------------------------------------------------------
# Die Konfig liegt im Windows-Benutzerprofil unter %APPDATA%\AC-SaveSync\.
# Dieser Ordner ist im Explorer standardmaessig ausgeblendet und liegt voellig
# getrennt vom Skript - es landet also nichts Sichtbares neben der .ps1.
$script:AppDir = if ($env:APPDATA) { Join-Path $env:APPDATA "AC-SaveSync" }
elseif ($env:LOCALAPPDATA) { Join-Path $env:LOCALAPPDATA "AC-SaveSync" }
else { Join-Path (Get-Location).Path "AC-SaveSync" }
if (-not (Test-Path $script:AppDir)) {
    New-Item -ItemType Directory -Path $script:AppDir -Force | Out-Null
}
$script:ConfigPath = Join-Path $script:AppDir "acsync-config.json"
# Eigener Pfad - fuer die Desktop-Verknuepfung. Beim Start ueber die .cmd
# setzt deren Kopf $PSCommandPath auf die .cmd, sonst ist es diese .ps1.
$script:SelfPath = $PSCommandPath
# Gibt es noch keine Einstellungsdatei, ist das der allererste Start -
# dann fuehrt der Assistent durch die Einrichtung (siehe Start-Timer).
$script:istErststart = -not (Test-Path $script:ConfigPath)

$script:defaults = @{
    DolphinPath      = "C:\Program Files\Dolphin-x64\Dolphin.exe"
    RepoPath         = "$env:USERPROFILE\Documents\ACSave"
    GamePath         = ""
    SaveFolder       = ""
    PicsFolder       = ""
    PlayerName       = $env:USERNAME
    Branch           = "main"
    LeaseMinutes     = 5
    HeartbeatSeconds = 60
}
$script:cfg = $script:defaults.Clone()

# Laufzeit-Zustand
$script:proc = $null
$script:holdingLock = $false
$script:lastHeartbeat = Get-Date
$script:lastAccounted = Get-Date
# Meldungen, die anfallen, bevor das Protokollfeld existiert (z. B. beim Laden
# der Konfig). Sie werden nachgetragen, sobald die Oberflaeche steht.
$script:pendingLog = @()
# Ist Git da? Wird beim Start einmal geprueft (siehe Start-Timer) und steuert,
# ob "Spielen starten" ueberhaupt anklickbar ist.
$script:gitDa = $true
# Ergebnis des letzten Speicherversuchs der Einstellungen (siehe Save-ConfigFromUI)
$script:configSaved = $false

function Import-Config {
    if (Test-Path $script:ConfigPath) {
        try {
            $j = Get-Content $script:ConfigPath -Raw | ConvertFrom-Json
            foreach ($k in @($script:cfg.Keys)) {
                if ($null -ne $j.$k -and "$($j.$k)" -ne "") { $script:cfg[$k] = $j.$k }
            }
        }
        catch {
            Write-Log "WARNUNG: Einstellungsdatei unlesbar - es gelten die Standardwerte."
            Write-Log ("  Datei: {0}" -f $script:ConfigPath)
            Write-Log ("  Grund: {0}" -f $_.Exception.Message)
        }
    }
}

function Save-ConfigFromUI {
    $script:cfg.DolphinPath = $script:txtDolphin.Text
    $script:cfg.RepoPath = $script:txtRepo.Text
    $script:cfg.GamePath = $script:txtGame.Text
    $script:cfg.SaveFolder = $script:txtSave.Text
    $script:cfg.PicsFolder = $script:txtPics.Text
    $script:cfg.PlayerName = $script:txtName.Text
    $script:cfg.Branch = $script:txtBranch.Text

    $lm = 5; [void][int]::TryParse($script:txtLease.Text, [ref]$lm)
    $hb = 60; [void][int]::TryParse($script:txtHeart.Text, [ref]$hb)
    if ($lm -lt 1) { $lm = 1 }
    if ($hb -lt 10) { $hb = 10 }
    $script:cfg.LeaseMinutes = $lm
    $script:cfg.HeartbeatSeconds = $hb

    # Ob das Schreiben geklappt hat, merken - sonst wuerde der Speichern-Knopf
    # "gespeichert" melden, obwohl die Datei nicht geschrieben werden konnte.
    $script:configSaved = $false
    try {
        ($script:cfg | ConvertTo-Json) | Set-Content -Path $script:ConfigPath -Encoding UTF8
        $script:configSaved = $true
    }
    catch {
        Write-Log "FEHLER: Einstellungen konnten nicht gespeichert werden."
        Write-Log ("  Datei: {0}" -f $script:ConfigPath)
        Write-Log ("  Grund: {0}" -f $_.Exception.Message)
    }
}

# --------------------------------------------------------------------------
# Kleine Helfer
# --------------------------------------------------------------------------
function Write-Log {
    param([string]$msg)
    $line = "[{0}] {1}`r`n" -f (Get-Date).ToString("HH:mm:ss"), $msg
    if ($script:txtLog) {
        # Zuerst nachtragen, was vor dem Fensteraufbau gemeldet wurde
        if ($script:pendingLog.Count -gt 0) {
            foreach ($p in $script:pendingLog) { $script:txtLog.AppendText($p) }
            $script:pendingLog = @()
        }
        $script:txtLog.AppendText($line)
        $script:txtLog.SelectionStart = $script:txtLog.Text.Length
        $script:txtLog.ScrollToCaret()
    }
    else {
        # Noch kein Protokollfeld -> merken und zusaetzlich in die Konsole
        $script:pendingLog += $line
        Write-Host $line
    }
}

# Macht aus der Ausgabe von git sauberen Text.
# Ohne das verpackt PowerShell alles, was git nach stderr schreibt, in
# ErrorRecords - und die werden mit "At C:\...:815 char:32", "CategoryInfo"
# usw. ausgegeben. Dieser Ballast verwirrt nur; uns interessiert der Satz,
# den git wirklich geschrieben hat.
function ConvertTo-GitText {
    param($Ausgabe)
    if ($null -eq $Ausgabe) { return "" }
    $zeilen = foreach ($z in @($Ausgabe)) {
        if ($z -is [System.Management.Automation.ErrorRecord]) { $z.Exception.Message }
        else { "$z" }
    }
    return (($zeilen -join "`r`n").Trim())
}

function Invoke-Git {
    param([string[]]$GitArgs)
    $out = & git -C $script:cfg.RepoPath @GitArgs 2>&1
    [pscustomobject]@{ Code = $LASTEXITCODE; Text = (ConvertTo-GitText $out) }
}

# --------------------------------------------------------------------------
# Automatisch finden, was man sonst von Hand zusammensuchen muesste
# --------------------------------------------------------------------------
# Sucht Dolphin an den ueblichen Stellen. Rueckgabe: Pfad zur Dolphin.exe
# oder "" - dann muss der Nutzer sie selbst auswaehlen.
function Find-DolphinExe {
    $orte = @(
        "$env:ProgramFiles\Dolphin-x64\Dolphin.exe"
        "$env:ProgramFiles\Dolphin\Dolphin.exe"
        "${env:ProgramFiles(x86)}\Dolphin-x64\Dolphin.exe"
        "${env:ProgramFiles(x86)}\Dolphin\Dolphin.exe"
        "$env:LOCALAPPDATA\Programs\Dolphin-x64\Dolphin.exe"
        "$env:LOCALAPPDATA\Programs\Dolphin\Dolphin.exe"
    )
    foreach ($o in $orte) {
        if ($o -and (Test-Path -LiteralPath $o)) { return $o }
    }

    # Portable Entpack-Installationen: irgendwo ein Ordner "Dolphin*" mit der
    # exe darin. Nur eine Ebene tief suchen - das bleibt schnell.
    $eltern = @(
        ([Environment]::GetFolderPath('MyDocuments'))
        ([Environment]::GetFolderPath('Desktop'))
        "$env:USERPROFILE\Downloads"
        "$env:ProgramFiles"
        "${env:ProgramFiles(x86)}"
        "$env:LOCALAPPDATA\Programs"
        "C:\", "C:\Games", "D:\", "D:\Games", "E:\"
    )
    foreach ($p in $eltern) {
        if (-not $p -or -not (Test-Path -LiteralPath $p)) { continue }
        try {
            foreach ($d in (Get-ChildItem -LiteralPath $p -Directory -Filter 'Dolphin*' -ErrorAction SilentlyContinue)) {
                $exe = Join-Path $d.FullName 'Dolphin.exe'
                if (Test-Path -LiteralPath $exe) { return $exe }
            }
        }
        catch { }
    }

    # Ueber die Deinstallations-Eintraege der Registry (deckt eigene Pfade ab)
    $wurzeln = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($w in $wurzeln) {
        try {
            foreach ($k in (Get-ItemProperty $w -ErrorAction SilentlyContinue)) {
                if ("$($k.DisplayName)" -like '*Dolphin*') {
                    $d = "$($k.InstallLocation)".Trim('"')
                    if ($d) {
                        $exe = Join-Path $d 'Dolphin.exe'
                        if (Test-Path -LiteralPath $exe) { return $exe }
                    }
                }
            }
        }
        catch { }
    }

    $c = Get-Command 'Dolphin.exe' -ErrorAction SilentlyContinue
    if ($c) { return $c.Source }
    return ""
}

# Sucht den Ordner, in dem Dolphin den Spielstand ablegt.
# Wenn moeglich wird direkt der Ordner von Animal Crossing zurueckgegeben -
# die Ordnernamen unter Wii\title\00010000 sind die Spielkuerzel in Hex:
#   52555545 = RUUE (USA), 52555550 = RUUP (Europa), 5255554A = RUUJ (Japan)
# Das ist deutlich besser als der Sammelordner, in dem ALLE Wii-Spiele liegen.
function Find-DolphinSaveFolder {
    param([string]$DolphinExe)
    $wurzeln = @()
    # Portable Installation: der User-Ordner liegt neben der Dolphin.exe
    if ($DolphinExe -and (Test-Path -LiteralPath $DolphinExe)) {
        $wurzeln += (Join-Path (Split-Path -Parent $DolphinExe) 'User')
    }
    $wurzeln += (Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'Dolphin Emulator')
    if ($env:APPDATA) { $wurzeln += (Join-Path $env:APPDATA 'Dolphin Emulator') }

    $acKuerzel = @('52555545', '52555550', '5255554a')

    # Von mehreren Kandidaten den zuletzt bespielten nehmen: wer zwei Regionen
    # installiert hat, spielt hoechstens eine davon wirklich.
    function Neuester($ordner) {
        $best = $null; $zeit = [datetime]::MinValue
        foreach ($o in $ordner) {
            $f = Get-ChildItem -LiteralPath $o -Recurse -File -ErrorAction SilentlyContinue |
                Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if ($f -and $f.LastWriteTime -gt $zeit) { $zeit = $f.LastWriteTime; $best = $o }
        }
        if ($best) { return $best }
        return ($ordner | Select-Object -First 1)
    }

    foreach ($w in $wurzeln) {
        $titel = Join-Path $w 'Wii\title\00010000'
        if (Test-Path -LiteralPath $titel) {
            # a) Animal Crossing direkt treffen
            $kandidaten = @()
            foreach ($k in $acKuerzel) {
                $p = Join-Path $titel $k
                if (Test-Path -LiteralPath $p) { $kandidaten += $p }
            }
            if ($kandidaten.Count -gt 0) { return (Neuester $kandidaten) }
            # b) genau ein Spiel vorhanden -> das ist es dann wohl
            $unter = @(Get-ChildItem -LiteralPath $titel -Directory -ErrorAction SilentlyContinue)
            if ($unter.Count -eq 1) { return $unter[0].FullName }
            # c) sonst der Sammelordner als grober Vorschlag
            if ($unter.Count -gt 1) { return $titel }
        }
        foreach ($u in @('Wii', 'GC')) {
            $p = Join-Path $w $u
            if (Test-Path -LiteralPath $p) { return $p }
        }
    }
    return ""
}

# Fuellt leere oder ins Leere zeigende Pfade mit dem, was gefunden wurde.
# Aendert NIE etwas, das der Nutzer selbst eingetragen hat und das existiert.
function Set-AutoPaths {
    $gefunden = @()

    if ([string]::IsNullOrWhiteSpace($script:cfg.DolphinPath) -or
        -not (Test-Path -LiteralPath $script:cfg.DolphinPath)) {
        $d = Find-DolphinExe
        if ($d) { $script:cfg.DolphinPath = $d; $gefunden += "Dolphin: $d" }
    }

    if ([string]::IsNullOrWhiteSpace($script:cfg.SaveFolder) -or
        -not (Test-Path -LiteralPath $script:cfg.SaveFolder)) {
        $s = Find-DolphinSaveFolder $script:cfg.DolphinPath
        if ($s) { $script:cfg.SaveFolder = $s; $gefunden += "Save-Ordner (Vorschlag): $s" }
    }

    foreach ($g in $gefunden) { Write-Log ("Automatisch gefunden - {0}" -f $g) }
    return $gefunden.Count
}

# --------------------------------------------------------------------------
# Git-Meldungen in Klartext uebersetzen
# --------------------------------------------------------------------------
# Git meldet Probleme knapp und auf Englisch. Diese Tabelle uebersetzt die
# haeufigsten Faelle in verstaendliches Deutsch samt Loesungsvorschlag.
# Die Originalmeldung wird IMMER zusaetzlich ausgegeben: sie deckt die Faelle
# ab, die hier fehlen, und ist beim Nachfragen in einem Forum Gold wert.
$script:GitKlartext = @(
    @{ Muster = 'could not read Username|could not read Password|Authentication failed|Invalid username or password|terminal prompts disabled|Permission denied \(publickey\)'
        Text  = 'Git kommt nicht auf den Server - die Zugangsdaten fehlen oder stimmen nicht.'
        Tipp  = 'Eingabeaufforderung im Repo-Ordner oeffnen und einmal "git push" ausfuehren, dann die Anmeldung abschliessen. Bei GitHub per Browser-Login oder mit einem Token als Passwort.' }
    @{ Muster = 'Could not resolve host|Failed to connect|Connection timed out|unable to access.*(Could not|Failed)|network is unreachable'
        Text  = 'Der Server ist nicht erreichbar - meist fehlt gerade die Internetverbindung.'
        Tipp  = 'Internetverbindung pruefen und es danach erneut versuchen. Der Spielstand bleibt solange lokal erhalten.' }
    @{ Muster = 'Repository not found|repository .* not found|remote: Not Found'
        Text  = 'Das Repo gibt es unter dieser Adresse nicht - oder dein Konto hat keinen Zugriff darauf.'
        Tipp  = 'Adresse auf Tippfehler pruefen. Bei einem privaten Repo muss dein Konto als Mitarbeiter eingetragen sein.' }
    @{ Muster = 'non-fast-forward|fetch first|Updates were rejected|behind its remote'
        Text  = 'Auf dem Server liegt ein neuerer Stand - jemand anderes war schneller.'
        Tipp  = 'Auf "Status pruefen" klicken, damit der neue Stand geholt wird, und es dann noch einmal versuchen.' }
    @{ Muster = 'Please tell me who you are|user\.email|user\.name|empty ident|unable to auto-detect email'
        Text  = 'Git weiss noch nicht, wer du bist - ohne Namen und E-Mail kann es nichts speichern.'
        Tipp  = 'Einmalig in einer Eingabeaufforderung ausfuehren:  git config --global user.name "Dein Name"  und  git config --global user.email "du@example.com"' }
    @{ Muster = 'not a git repository|does not appear to be a git repository'
        Text  = 'Der eingetragene Ordner ist kein Git-Repo.'
        Tipp  = 'Pfad beim Repo-Ordner pruefen, oder unten auf "Repo einrichten..." klicken.' }
    @{ Muster = "'origin' does not appear|No such remote|remote origin already exists"
        Text  = 'Die Verbindung zum gemeinsamen Repo im Internet ("origin") ist nicht richtig eingerichtet.'
        Tipp  = 'Ueber "Repo einrichten..." Schritt 2 die Adresse des gemeinsamen Repos eintragen.' }
    @{ Muster = 'src refspec .* does not match any|couldn.t find remote ref'
        Text  = 'Den eingetragenen Branch gibt es noch nicht.'
        Tipp  = 'Pruefen, ob beide Spieler denselben Branch eingetragen haben (normalerweise "main").' }
    @{ Muster = 'index\.lock|Unable to create .*index\.lock'
        Text  = 'Git blockiert sich selbst - vermutlich laeuft noch ein anderer Git-Vorgang oder einer ist abgestuerzt.'
        Tipp  = 'Kurz warten und erneut versuchen. Hilft das nicht, die Datei .git\index.lock im Repo-Ordner loeschen.' }
    @{ Muster = 'would be overwritten by merge|local changes.*would be overwritten|CONFLICT|Automatic merge failed'
        Text  = 'Lokale Aenderungen stehen dem Stand vom Server im Weg.'
        Tipp  = 'Meist reicht "Status pruefen" - das holt den Server-Stand. Achtung: dabei werden lokale Aenderungen verworfen.' }
    @{ Muster = 'Filename too long|unable to write file.*too long|path too long'
        Text  = 'Ein Dateiname wird zu lang - Windows steigt bei sehr langen Pfaden aus.'
        Tipp  = 'Einmalig ausfuehren:  git config --global core.longpaths true  - oder den Repo-Ordner naeher an die Laufwerkswurzel legen, z. B. C:\ACSave.' }
    @{ Muster = 'detected dubious ownership|safe\.directory'
        Text  = 'Git traut dem Ordner nicht, weil er einem anderen Benutzerkonto gehoert.'
        Tipp  = 'Einmalig ausfuehren:  git config --global --add safe.directory "<Pfad zum Repo-Ordner>"' }
)

# Gibt einen Git-Fehler verstaendlich aus: erst Klartext + Tipp, danach immer
# die unveraenderte Originalmeldung.
function Write-GitProblem {
    param([string]$Titel, $Ergebnis)
    Write-Log "FEHLER: $Titel"
    $t = "$($Ergebnis.Text)"
    $erklaert = $false
    foreach ($e in $script:GitKlartext) {
        if ($t -match $e.Muster) {
            Write-Log ("  Das heisst: {0}" -f $e.Text)
            Write-Log ("  Das hilft:  {0}" -f $e.Tipp)
            $erklaert = $true
            break
        }
    }
    if (-not $erklaert) {
        Write-Log "  Fuer diesen Fall habe ich keine Uebersetzung - die Originalmeldung steht direkt darunter."
    }
    if (-not [string]::IsNullOrWhiteSpace($t)) {
        Write-Log "  Originalmeldung von Git:"
        foreach ($z in ($t -split "`r?`n")) {
            if ($z.Trim()) { Write-Log ("    {0}" -f $z.TrimEnd()) }
        }
    }
}

function Test-Repo {
    if (-not (Test-Path (Join-Path $script:cfg.RepoPath ".git"))) {
        Write-Log "FEHLER: Unter RepoPath liegt kein Git-Repo. Bitte erst das gemeinsame Repo dorthin klonen."
        return $false
    }
    return $true
}

# Auf den Remote-Stand zwingen (kein Merge -> keine Konflikte).
# Nur aufrufen, wenn wir die Sperre NICHT halten (sonst wuerden wir eigenen
# Fortschritt verwerfen).
function Sync-Remote {
    $f = Invoke-Git @('fetch', 'origin')
    if ($f.Code -ne 0) { Write-GitProblem "Der Stand vom Server konnte nicht geholt werden." $f }
    $r = Invoke-Git @('reset', '--hard', "origin/$($script:cfg.Branch)")
    if ($r.Code -ne 0) { Write-GitProblem "Der Stand vom Server konnte nicht uebernommen werden." $r }
}

function Get-LockPath { Join-Path $script:cfg.RepoPath "PLAYING.lock" }

function Set-LockFile {
    $obj = [ordered]@{
        owner      = $script:cfg.PlayerName
        machine    = $env:COMPUTERNAME
        updatedUtc = [datetime]::UtcNow.ToString("o")
    }
    ($obj | ConvertTo-Json) | Set-Content -Path (Get-LockPath) -Encoding UTF8
}

function Get-LockState {
    $lf = Get-LockPath
    if (-not (Test-Path $lf)) { return [pscustomobject]@{ State = 'free' } }
    try {
        $j = Get-Content $lf -Raw -ErrorAction Stop | ConvertFrom-Json
        $upd = [datetimeoffset]::Parse($j.updatedUtc).UtcDateTime
        $age = ([datetime]::UtcNow - $upd).TotalMinutes
        $mine = ($j.owner -eq $script:cfg.PlayerName) -and ($j.machine -eq $env:COMPUTERNAME)
        return [pscustomobject]@{
            State      = 'locked'
            Owner      = $j.owner
            Machine    = $j.machine
            AgeMinutes = $age
            Stale      = ($age -gt $script:cfg.LeaseMinutes)
            Mine       = $mine
        }
    }
    catch {
        return [pscustomobject]@{ State = 'unknown' }
    }
}

# Liegt etwas zum Committen bereit? Ueber den Exitcode statt ueber den
# Ausgabetext ("nothing to commit"), damit es auch mit anderssprachigem Git
# funktioniert:  0 = Index deckt sich mit HEAD,  1 = es gibt Vorgemerktes.
function Test-Staged {
    return ((Invoke-Git @('diff', '--cached', '--quiet')).Code -ne 0)
}

# Committet die aktuellen Aenderungen und pusht sie. Rueckgabe wie Invoke-Git,
# damit der Aufrufer an .Code erkennt, ob wirklich alles beim Remote angekommen
# ist. WICHTIG: Scheitert schon der Commit, wird NICHT gepusht und der Fehler
# durchgereicht - sonst wuerde ein "Everything up-to-date" des Push einen
# Erfolg vortaeuschen und z. B. eine Sperre als gesichert gelten, die nie
# beim anderen Spieler ankommt.
function Invoke-GitCommitPush {
    param([string]$msg)
    Invoke-Git @('add', '-A') | Out-Null
    if (Test-Staged) {
        $c = Invoke-Git @('commit', '-m', $msg)
        if ($c.Code -ne 0) {
            Write-GitProblem "Speichern fehlgeschlagen - es wird nichts hochgeladen." $c
            return [pscustomobject]@{ Code = $c.Code; Text = $c.Text; Stage = 'commit' }
        }
    }
    # Auch ohne neuen Commit pushen: es koennen aeltere Commits liegen
    # geblieben sein, deren Push beim letzten Mal fehlgeschlagen ist.
    $p = Invoke-Git @('push', 'origin', $script:cfg.Branch)
    return [pscustomobject]@{ Code = $p.Code; Text = $p.Text; Stage = 'push' }
}

function Update-StatusUI {
    param($lock)
    switch ($lock.State) {
        'free' {
            $script:lblStatus.Text = "FREI  -  niemand spielt gerade"
            $script:lblStatus.BackColor = [Drawing.Color]::FromArgb(200, 240, 200)
        }
        'locked' {
            if ($lock.Mine) {
                $script:lblStatus.Text = "DU spielst gerade  (Sperre liegt bei dir)"
                $script:lblStatus.BackColor = [Drawing.Color]::FromArgb(200, 220, 255)
            }
            elseif ($lock.Stale) {
                $script:lblStatus.Text = ("ABGELAUFENE Sperre von {0}  (seit {1} Min)  -  kann uebernommen werden" -f $lock.Owner, [math]::Round($lock.AgeMinutes, 1))
                $script:lblStatus.BackColor = [Drawing.Color]::FromArgb(255, 235, 180)
            }
            else {
                $script:lblStatus.Text = ("GESPERRT  -  {0} spielt  (seit {1} Min)" -f $lock.Owner, [math]::Round($lock.AgeMinutes, 1))
                $script:lblStatus.BackColor = [Drawing.Color]::FromArgb(255, 200, 200)
            }
        }
        default {
            $script:lblStatus.Text = "Status unbekannt (Sperr-Datei unlesbar)"
            $script:lblStatus.BackColor = [Drawing.Color]::FromArgb(230, 230, 230)
        }
    }
}

# --------------------------------------------------------------------------
# Ablauf: Spielen starten
# --------------------------------------------------------------------------
function Start-Play {
    Save-ConfigFromUI

    if (-not (Test-Path $script:cfg.DolphinPath)) {
        Write-Log "FEHLER: Dolphin nicht gefunden unter: $($script:cfg.DolphinPath)"
        return
    }
    if (-not (Test-Repo)) { return }

    Write-Log "Synchronisiere mit dem Remote-Repo..."
    Sync-Remote
    $lock = Get-LockState
    Update-StatusUI $lock

    if ($lock.State -eq 'locked' -and -not $lock.Mine -and -not $lock.Stale) {
        Write-Log ("GESPERRT: {0} spielt gerade (seit {1} Min). Bitte warten." -f $lock.Owner, [math]::Round($lock.AgeMinutes, 1))
        return
    }
    if ($lock.State -eq 'locked' -and $lock.Stale) {
        Write-Log ("Alte Sperre von {0} ist abgelaufen -> ich uebernehme." -f $lock.Owner)
    }

    # Sperre sichern (mit Wettlauf-Schutz: wer zuerst pusht, gewinnt)
    $acquired = $false
    for ($i = 1; $i -le 3 -and -not $acquired; $i++) {
        Set-LockFile
        $p = Invoke-GitCommitPush ("lock: {0}" -f $script:cfg.PlayerName)
        if ($p.Code -eq 0) { $acquired = $true; break }

        # Scheitert schon der Commit, hilft kein zweiter Versuch - das ist kein
        # Wettlauf, sondern ein Problem am lokalen Git (siehe Meldung oben).
        if ($p.Stage -eq 'commit') {
            Write-Log "Abbruch: die Sperre konnte lokal nicht committet werden."
            return
        }

        Write-Log "Push abgelehnt (Versuch $i) - jemand war evtl. schneller. Pruefe erneut..."
        Sync-Remote
        $lock = Get-LockState
        if ($lock.State -eq 'locked' -and -not $lock.Mine -and -not $lock.Stale) {
            Update-StatusUI $lock
            Write-Log ("GESPERRT: {0} war schneller. Abbruch." -f $lock.Owner)
            return
        }
    }
    if (-not $acquired) {
        Write-Log "Abbruch: die Sperre konnte nicht gesichert werden."
        Write-Log "Tipp: 'Selbsttest' zeigt, woran es liegt."
        return
    }

    Write-Log "Sperre gesichert. Starte Dolphin..."
    $script:holdingLock = $true

    Restore-Saves | Out-Null

    try {
        $gp = $script:cfg.GamePath
        if ($gp -and (Test-Path $gp)) {
            $ext = [IO.Path]::GetExtension($gp).ToLowerInvariant()

            if ($ext -eq '.lnk') {
                # Verknuepfung aufloesen und Dolphin direkt mit denselben Argumenten
                # starten (-> zuverlaessiger Prozess-Handle fuers Sitzungsende,
                # und dein Mod-Preset laeuft genau wie beim Doppelklick auf die .lnk).
                $tgt = $null; $ar = ""
                try {
                    $wsh = New-Object -ComObject WScript.Shell
                    $sc = $wsh.CreateShortcut($gp)
                    $tgt = $sc.TargetPath
                    $ar = $sc.Arguments
                }
                catch { $tgt = $null }

                if ([string]::IsNullOrWhiteSpace($tgt) -or -not (Test-Path $tgt)) {
                    Write-Log "Verknuepfung nicht aufloesbar - starte sie direkt."
                    $script:proc = Start-Process -FilePath $gp -PassThru
                }
                else {
                    Write-Log ("Starte via Verknuepfung: `"{0}`" {1}" -f $tgt, $ar)
                    if ([string]::IsNullOrWhiteSpace($ar)) {
                        $script:proc = Start-Process -FilePath $tgt -PassThru
                    }
                    else {
                        $script:proc = Start-Process -FilePath $tgt -ArgumentList $ar -PassThru
                    }
                }
            }
            elseif ($ext -eq '.exe' -or $ext -eq '.bat' -or $ext -eq '.cmd') {
                # Ein Programm/Skript, das sich selbst um Dolphin + Mods kuemmert.
                $script:proc = Start-Process -FilePath $gp -PassThru
            }
            else {
                # Normale Spiel-/Preset-Datei an Dolphin uebergeben.
                # Pfad in Anfuehrungszeichen -> Leerzeichen im Pfad sind kein Problem.
                $argStr = '-b -e "{0}"' -f $gp
                Write-Log ("Starte Dolphin mit: {0}" -f $argStr)
                $script:proc = Start-Process -FilePath $script:cfg.DolphinPath -ArgumentList $argStr -PassThru
            }
        }
        else {
            $script:proc = Start-Process -FilePath $script:cfg.DolphinPath -PassThru
        }
    }
    catch {
        Write-Log "Start fehlgeschlagen: $_"
        Complete-Session
        return
    }

    $script:lastHeartbeat = Get-Date
    $script:lastAccounted = Get-Date
    $script:btnPlay.Enabled = $false
    $script:btnStop.Enabled = $true
    Update-StatusUI (Get-LockState)
    $script:timer.Start()
    Write-Log "Viel Spass. Beim Schliessen von Dolphin - oder mit 'Spielen beenden' - wird automatisch gespeichert & freigegeben."
}

# --------------------------------------------------------------------------
# Herzschlag + Ende-Erkennung (laeuft im Timer-Tick)
# --------------------------------------------------------------------------
function Invoke-Tick {
    if ($null -ne $script:proc -and $script:proc.HasExited) {
        Complete-Session
        return
    }
    if (((Get-Date) - $script:lastHeartbeat).TotalSeconds -ge $script:cfg.HeartbeatSeconds) {
        Set-LockFile
        Backup-Saves | Out-Null
        Add-Playtime
        $p = Invoke-GitCommitPush ("heartbeat: {0}" -f $script:cfg.PlayerName)
        if ($p.Code -ne 0) {
            Write-GitProblem "Zwischenspeichern waehrend des Spielens hat nicht geklappt." $p
            Write-Log "  Das Spiel laeuft normal weiter - es wird beim naechsten Herzschlag erneut versucht."
        }
        else {
            Write-Log "Herzschlag gesendet (Spielstand + Sperre aktualisiert)."
        }
        $script:lastHeartbeat = Get-Date
    }
}

function Complete-Session {
    if ($script:timer) { $script:timer.Stop() }
    if (-not $script:holdingLock) {
        $script:btnPlay.Enabled = $true
        $script:btnStop.Enabled = $false
        return
    }

    Write-Log "Dolphin beendet. Speichere Fortschritt und gebe Sperre frei..."
    Backup-Saves | Out-Null
    Move-Pics
    Add-Playtime -EndSession
    $lf = Get-LockPath
    Remove-Item $lf -Force -ErrorAction SilentlyContinue
    $p = Invoke-GitCommitPush ("Session beendet + Spielstand ({0})" -f $script:cfg.PlayerName)

    if ($p.Code -ne 0) {
        Write-GitProblem "Hochladen beim Beenden fehlgeschlagen." $p
        Write-Log "  Keine Panik: dein Fortschritt ist lokal gespeichert und nicht verloren."
        Write-Log "  Er wird beim naechsten erfolgreichen Hochladen mitgenommen."
    }
    else {
        Write-Log "Fertig. Spielstand hochgeladen, Sperre freigegeben."
    }

    $script:holdingLock = $false
    $script:proc = $null
    $script:btnPlay.Enabled = $true
    $script:btnStop.Enabled = $false
    [void](Update-ReadyState)
    Update-StatusUI (Get-LockState)
}

# Dolphin aus dem Programm heraus beenden (Knopf "Spielen beenden").
# Erst hoeflich bitten (CloseMainWindow = wie auf das X klicken), damit Dolphin
# sauber herunterfaehrt. Nur wenn das nichts bringt, auf Nachfrage hart abbrechen.
# Danach laeuft alles Weitere ueber Complete-Session - also genau derselbe Weg
# wie beim Schliessen von Hand: sichern, hochladen, Sperre freigeben.
function Stop-Play {
    if (-not $script:holdingLock -or $null -eq $script:proc) {
        Write-Log "Es laeuft gerade keine Sitzung."
        return
    }
    if ($script:proc.HasExited) { Complete-Session; return }

    $r = [Windows.Forms.MessageBox]::Show(
        ("Dolphin jetzt beenden?`n`n" +
        "WICHTIG: Speichere vorher IM SPIEL. Alles seit dem letzten Speichern " +
        "im Spiel ist sonst weg - das Skript kann nur sichern, was Dolphin " +
        "bereits auf die Festplatte geschrieben hat.`n`n" +
        "Danach wird der Spielstand hochgeladen und die Sperre freigegeben."),
        "Spielen beenden", 'YesNo', 'Warning')
    if ($r -ne 'Yes') { return }

    # Timer anhalten, damit die Ende-Erkennung nicht parallel Complete-Session
    # aufruft, waehrend wir hier noch warten.
    $script:timer.Stop()
    $script:btnStop.Enabled = $false
    Write-Log "Beende Dolphin..."

    $asked = $false
    try {
        $script:proc.Refresh()
        if ($script:proc.MainWindowHandle -ne [IntPtr]::Zero) {
            $asked = $script:proc.CloseMainWindow()
        }
    }
    catch { $asked = $false }

    if (-not $asked) {
        Write-Log "Dolphin hat kein normales Fenster zum Schliessen (z. B. bei einem Starter-Skript)."
    }
    else {
        # Bis zu 20 s Zeit lassen. DoEvents haelt unser Fenster bedienbar und
        # laesst Dolphin seine eigene Rueckfrage anzeigen.
        $ende = (Get-Date).AddSeconds(20)
        while (-not $script:proc.HasExited -and (Get-Date) -lt $ende) {
            [Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 200
        }
    }

    if (-not $script:proc.HasExited) {
        $f = [Windows.Forms.MessageBox]::Show(
            ("Dolphin laesst sich nicht normal beenden.`n`n" +
            "Hart abbrechen? Was Dolphin noch nicht auf die Festplatte " +
            "geschrieben hat, geht dabei verloren."),
            "Beenden erzwingen", 'YesNo', 'Warning')
        if ($f -eq 'Yes') {
            try {
                $script:proc.Kill()
                [void]$script:proc.WaitForExit(5000)
            }
            catch { Write-Log "Konnte Dolphin nicht beenden: $($_.Exception.Message)" }
        }
    }

    if (-not $script:proc.HasExited) {
        # Nichts kaputtgemacht: Sitzung laeuft weiter wie vorher.
        Write-Log "Dolphin laeuft weiter - Sitzung bleibt offen."
        $script:btnStop.Enabled = $true
        $script:timer.Start()
        return
    }

    Complete-Session
}

# --------------------------------------------------------------------------
# Notausgang + Statusknopf
# --------------------------------------------------------------------------
function Unlock-Session {
    Save-ConfigFromUI
    if ($script:holdingLock) {
        Write-Log "Du haeltst die Sperre selbst - nimm 'Spielen beenden' (oder schliesse Dolphin), dann wird sie normal freigegeben."
        return
    }
    if (-not (Test-Repo)) { return }
    $r = [Windows.Forms.MessageBox]::Show(
        "Sperre wirklich zwangsweise freigeben?`n`nNur benutzen, wenn sicher ist, dass niemand spielt (z. B. nach einem Absturz).",
        "Sperre erzwingen", 'YesNo', 'Warning')
    if ($r -ne 'Yes') { return }

    Sync-Remote
    $lf = Get-LockPath
    if (Test-Path $lf) { Remove-Item $lf -Force }
    $p = Invoke-GitCommitPush ("force-unlock durch {0}" -f $script:cfg.PlayerName)
    if ($p.Code -eq 0) { Write-Log "Sperre wurde zwangsweise freigegeben." }
    else { Write-GitProblem "Die Sperre konnte nicht freigegeben werden." $p }
    Update-StatusUI (Get-LockState)
}

# Sperrt "Spielen starten", solange etwas Wichtiges fehlt - und sagt im
# Kurzhinweis am Knopf, WAS fehlt. Besser, als den Nutzer erst beim Klick
# in eine Fehlermeldung laufen zu lassen.
function Update-ReadyState {
    # Waehrend einer Sitzung steuern Start-Play/Complete-Session die Knoepfe.
    if ($script:holdingLock) { return }

    $fehlt = @()
    if (-not $script:gitDa) { $fehlt += "Git ist nicht installiert" }
    if ([string]::IsNullOrWhiteSpace($script:cfg.PlayerName)) { $fehlt += "dein Name ist leer" }
    if ([string]::IsNullOrWhiteSpace($script:cfg.DolphinPath) -or
        -not (Test-Path -LiteralPath $script:cfg.DolphinPath)) { $fehlt += "Dolphin wurde nicht gefunden" }
    if ([string]::IsNullOrWhiteSpace($script:cfg.RepoPath) -or
        -not (Test-Path (Join-Path $script:cfg.RepoPath '.git'))) { $fehlt += "der gemeinsame Ordner ist noch kein Repo" }

    $bereit = ($fehlt.Count -eq 0)
    $script:btnPlay.Enabled = $bereit
    if ($bereit) {
        Set-Tip ("Der normale Weg zum Spielen:`n" +
            "holt den neuesten Spielstand, setzt die Sperre auf deinen Namen`n" +
            "und startet Dolphin. Bricht ab, wenn jemand anderes gerade spielt.`n" +
            "Beim Beenden von Dolphin wird automatisch gesichert, hochgeladen`n" +
            "und die Sperre wieder freigegeben.") $script:btnPlay
    }
    else {
        Set-Tip ("Noch nicht startklar - es fehlt:`n- " + ($fehlt -join "`n- ") +
            "`n`nDer Knopf 'Selbsttest' zeigt im Detail, was zu tun ist.") $script:btnPlay
    }
    return $fehlt
}

function Update-Status {
    # Beim Klick auf "Status pruefen" werden die Felder mitgespeichert.
    # Beim automatischen Start-Check nicht: sonst wuerde das blosse Oeffnen
    # des Fensters die Einstellungen ueberschreiben.
    param([switch]$SkipSave)
    if (-not $SkipSave) { Save-ConfigFromUI }
    if (-not (Test-Repo)) { return }
    Write-Log "Pruefe aktuellen Status..."
    Sync-Remote
    $lock = Get-LockState
    Update-StatusUI $lock
    if ($lock.State -eq 'free') { Write-Log "Frei - du kannst spielen." }
    elseif ($lock.Mine) { Write-Log "Die Sperre liegt bei dir." }
    elseif ($lock.Stale) { Write-Log ("Abgelaufene Sperre von {0} - kann uebernommen werden." -f $lock.Owner) }
    else { Write-Log ("{0} spielt gerade." -f $lock.Owner) }
}

# --------------------------------------------------------------------------
# Selbsttest: "Ist alles startklar?"
# --------------------------------------------------------------------------
# Ruft git auch ausserhalb des Repos auf (fuer --version und --global config)
# und faengt ab, dass git ueberhaupt fehlt.
function Invoke-GitRaw {
    param([string[]]$GitArgs, [string]$WorkDir)
    try {
        if ($WorkDir) { $out = & git -C $WorkDir @GitArgs 2>&1 }
        else { $out = & git @GitArgs 2>&1 }
        return [pscustomobject]@{ Code = $LASTEXITCODE; Text = (ConvertTo-GitText $out) }
    }
    catch {
        # git nicht gefunden -> 9009 ist Windows' "Befehl nicht gefunden"
        return [pscustomobject]@{ Code = 9009; Text = $_.Exception.Message }
    }
}

# Prueft der Reihe nach alles, was zum Spielen noetig ist.
# Rueckgabe: Liste aus Name / Ok / Hinweis / Roh (Originalmeldung von Git).
function Test-Setup {
    $e = @()
    function Neu($name, $ok, $hinweis, $roh = "") {
        [pscustomobject]@{ Name = $name; Ok = $ok; Hinweis = $hinweis; Roh = $roh }
    }

    # 1) Git ueberhaupt da?
    $v = Invoke-GitRaw @('--version')
    if ($v.Code -ne 0) {
        $e += Neu "Git installiert" $false ("Git fehlt - ohne Git kann nichts ausgetauscht werden. " +
            "Kostenlos herunterladen unter https://git-scm.com/download/win, installieren, " +
            "danach dieses Programm neu starten.") $v.Text
        # Alles Weitere braucht Git - hier ist Schluss.
        $e += Neu "Weitere Pruefungen" $false "Uebersprungen, weil Git fehlt." ""
        return $e
    }
    $e += Neu "Git installiert" $true $v.Text

    # 2) Kennt Git meinen Namen? (sonst schlaegt jeder Commit fehl)
    $n = Invoke-GitRaw @('config', '--global', 'user.name')
    $m = Invoke-GitRaw @('config', '--global', 'user.email')
    if ([string]::IsNullOrWhiteSpace($n.Text) -or [string]::IsNullOrWhiteSpace($m.Text)) {
        $e += Neu "Git kennt dich" $false ('Git fehlen Name und E-Mail. Einmalig in einer Eingabeaufforderung: ' +
            'git config --global user.name "Dein Name"  und  git config --global user.email "du@example.com"') ""
    }
    else {
        $e += Neu "Git kennt dich" $true ("{0} <{1}>" -f $n.Text, $m.Text)
    }

    # 3) Spielername im Programm
    if ([string]::IsNullOrWhiteSpace($script:cfg.PlayerName)) {
        $e += Neu "Dein Name" $false "Oben bei 'Dein Name' etwas eintragen. Wichtig: beide Spieler brauchen UNTERSCHIEDLICHE Namen." ""
    }
    else {
        $e += Neu "Dein Name" $true $script:cfg.PlayerName
    }

    # 4) Dolphin
    if ([string]::IsNullOrWhiteSpace($script:cfg.DolphinPath) -or -not (Test-Path -LiteralPath $script:cfg.DolphinPath)) {
        $e += Neu "Dolphin gefunden" $false ("Unter '" + $script:cfg.DolphinPath + "' liegt keine Dolphin.exe. " +
            "Oben ueber '...' die richtige Datei auswaehlen.") ""
    }
    else {
        $e += Neu "Dolphin gefunden" $true $script:cfg.DolphinPath
    }

    # 5) Save-Ordner. Bewusst hier und nicht am Ende: die Pruefungen danach
    # koennen abbrechen, dieser Punkt ist aber immer feststellbar.
    if ([string]::IsNullOrWhiteSpace($script:cfg.SaveFolder)) {
        $e += Neu "Save-Ordner" $false "Leer - Spielstaende werden NICHT synchronisiert. Nur sinnvoll, wenn ihr das absichtlich so wollt." ""
    }
    elseif (-not (Test-Path -LiteralPath $script:cfg.SaveFolder)) {
        $e += Neu "Save-Ordner" $false ("'" + $script:cfg.SaveFolder + "' gibt es nicht. Oben ueber '...' den Ordner auswaehlen, in dem Dolphin die Spielstaende ablegt.") ""
    }
    else {
        $e += Neu "Save-Ordner" $true $script:cfg.SaveFolder
    }

    # 6) Repo-Ordner
    $istRepo = (-not [string]::IsNullOrWhiteSpace($script:cfg.RepoPath)) -and
               (Test-Path (Join-Path $script:cfg.RepoPath '.git'))
    if (-not $istRepo) {
        $e += Neu "Gemeinsamer Ordner" $false ("Unter '" + $script:cfg.RepoPath + "' liegt kein Git-Repo. " +
            "Unten auf 'Repo einrichten...' klicken - oder den Ordner korrigieren.") ""
        $e += Neu "Verbindung zum Server" $false "Uebersprungen, weil noch kein Repo da ist." ""
        return $e
    }
    $e += Neu "Gemeinsamer Ordner" $true $script:cfg.RepoPath

    # 6) Ist eine Adresse im Internet hinterlegt?
    $o = Invoke-GitRaw @('remote', 'get-url', 'origin') $script:cfg.RepoPath
    if ($o.Code -ne 0 -or [string]::IsNullOrWhiteSpace($o.Text)) {
        $e += Neu "Adresse des Repos" $false ("Es ist keine Adresse ('origin') hinterlegt - der Austausch mit dem " +
            "anderen Spieler kann so nicht funktionieren. Ueber 'Repo einrichten...', Schritt 2.") $o.Text
        return $e
    }
    $e += Neu "Adresse des Repos" $true $o.Text

    # 7) Server erreichbar + Zugangsdaten in Ordnung?
    $ls = Invoke-GitRaw @('ls-remote', '--heads', 'origin') $script:cfg.RepoPath
    if ($ls.Code -ne 0) {
        $klar = "Der Server antwortet nicht wie erwartet."
        foreach ($k in $script:GitKlartext) {
            if ("$($ls.Text)" -match $k.Muster) { $klar = $k.Text + " " + $k.Tipp; break }
        }
        $e += Neu "Verbindung zum Server" $false $klar $ls.Text
        return $e
    }
    $e += Neu "Verbindung zum Server" $true "Server erreichbar, Zugang funktioniert."

    # 8) Gibt es den eingetragenen Branch dort?
    if ($ls.Text -match ("refs/heads/" + [regex]::Escape($script:cfg.Branch) + '\s*$') -or
        $ls.Text -match ("refs/heads/" + [regex]::Escape($script:cfg.Branch) + '[\r\n]')) {
        $e += Neu "Branch vorhanden" $true $script:cfg.Branch
    }
    else {
        $e += Neu "Branch vorhanden" $false ("Auf dem Server gibt es keinen Branch '" + $script:cfg.Branch +
            "'. Pruefen, ob beide Spieler denselben Branch eingetragen haben (meist 'main').") $ls.Text
    }

    return $e
}

# Zeigt das Ergebnis als Ampel-Liste. Zu jedem Punkt der Klartext-Hinweis und,
# wo vorhanden, die Originalmeldung von Git.
function Show-SelfTest {
    Save-ConfigFromUI
    Write-Log "Selbsttest laeuft..."
    [Windows.Forms.Application]::DoEvents()
    $erg = Test-Setup

    $dlg = New-Object Windows.Forms.Form
    $dlg.Text = "Selbsttest - ist alles startklar?"
    $dlg.Size = New-Object Drawing.Size(660, 560)
    $dlg.StartPosition = "CenterParent"
    $dlg.MinimumSize = New-Object Drawing.Size(520, 360)
    if ($script:appIcon) { $dlg.Icon = $script:appIcon }

    $kopf = New-Object Windows.Forms.Label
    $anzahlFehler = @($erg | Where-Object { -not $_.Ok }).Count
    $kopf.Text = if ($anzahlFehler -eq 0) { "Alles in Ordnung - ihr koennt loslegen." }
    else { "$anzahlFehler Punkt(e) brauchen noch Aufmerksamkeit. Details stehen darunter." }
    $kopf.Font = New-Object Drawing.Font("Segoe UI", 10, [Drawing.FontStyle]::Bold)
    $kopf.Location = New-Object Drawing.Point(15, 12)
    $kopf.Size = New-Object Drawing.Size(610, 24)
    $kopf.Anchor = 'Top,Left,Right'
    $dlg.Controls.Add($kopf)

    $panel = New-Object Windows.Forms.Panel
    $panel.Location = New-Object Drawing.Point(15, 44)
    $panel.Size = New-Object Drawing.Size(612, 430)
    $panel.AutoScroll = $true
    $panel.BorderStyle = 'FixedSingle'
    $panel.Anchor = 'Top,Bottom,Left,Right'
    $dlg.Controls.Add($panel)

    $py = 8
    foreach ($p in $erg) {
        $zeile = New-Object Windows.Forms.Label
        $zeile.Text = if ($p.Ok) { "OK      " + $p.Name } else { "FEHLT   " + $p.Name }
        $zeile.ForeColor = if ($p.Ok) { [Drawing.Color]::FromArgb(0, 110, 0) } else { [Drawing.Color]::FromArgb(170, 0, 0) }
        $zeile.Font = New-Object Drawing.Font("Segoe UI", 9.75, [Drawing.FontStyle]::Bold)
        $zeile.Location = New-Object Drawing.Point(10, $py)
        $zeile.Size = New-Object Drawing.Size(570, 20)
        $panel.Controls.Add($zeile)
        $py += 20

        if ($p.Hinweis) {
            $h = New-Object Windows.Forms.Label
            $h.Text = $p.Hinweis
            $h.Location = New-Object Drawing.Point(28, $py)
            $h.Size = New-Object Drawing.Size(550, 0)
            $h.AutoSize = $false
            $h.MaximumSize = New-Object Drawing.Size(550, 0)
            $h.AutoSize = $true
            $h.ForeColor = [Drawing.Color]::FromArgb(70, 70, 70)
            $panel.Controls.Add($h)
            $py += $h.Height + 4
        }

        # Originalmeldung von Git immer mit anzeigen, wenn es eine gibt
        if ($p.Roh -and -not $p.Ok) {
            $r = New-Object Windows.Forms.TextBox
            $r.Text = $p.Roh
            $r.Multiline = $true
            $r.ReadOnly = $true
            $r.ScrollBars = 'Vertical'
            $r.Font = New-Object Drawing.Font("Consolas", 8.5)
            $r.BackColor = [Drawing.Color]::FromArgb(245, 245, 245)
            $r.Location = New-Object Drawing.Point(28, $py)
            $zeilen = @($p.Roh -split "`r?`n").Count
            $r.Size = New-Object Drawing.Size(550, [Math]::Min(90, 16 + 13 * $zeilen))
            $panel.Controls.Add($r)
            $py += $r.Height + 4
        }
        $py += 8
    }

    $btnKopieren = New-Object Windows.Forms.Button
    $btnKopieren.Text = "Bericht kopieren"
    $btnKopieren.Location = New-Object Drawing.Point(15, 484)
    $btnKopieren.Size = New-Object Drawing.Size(150, 30)
    $btnKopieren.Anchor = 'Bottom,Left'
    $script:selfTestBericht = ($erg | ForEach-Object {
            $k = if ($_.Ok) { "OK   " } else { "FEHLT" }
            "[$k] $($_.Name)`r`n       $($_.Hinweis)" + $(if ($_.Roh -and -not $_.Ok) { "`r`n       git: " + ($_.Roh -replace "`r?`n", "`r`n            ") } else { "" })
        }) -join "`r`n"
    $btnKopieren.Add_Click({
            try { [Windows.Forms.Clipboard]::SetText($script:selfTestBericht) } catch { }
        })
    $dlg.Controls.Add($btnKopieren)
    Set-Tip ("Kopiert das ganze Ergebnis als Text - praktisch, wenn du`n" +
        "jemanden um Hilfe bittest.") $btnKopieren

    $btnZu = New-Object Windows.Forms.Button
    $btnZu.Text = "Schliessen"
    $btnZu.Location = New-Object Drawing.Point(497, 484)
    $btnZu.Size = New-Object Drawing.Size(130, 30)
    $btnZu.Anchor = 'Bottom,Right'
    $btnZu.Add_Click({ $script:selfTestDlg.Close() })
    $dlg.Controls.Add($btnZu)
    $script:selfTestDlg = $dlg

    foreach ($p in $erg) {
        Write-Log ("  [{0}] {1}" -f $(if ($p.Ok) { "OK" } else { "FEHLT" }), $p.Name)
    }
    Write-Log ("Selbsttest fertig: {0} Punkt(e) offen." -f $anzahlFehler)

    [void]$dlg.ShowDialog()
}

# --------------------------------------------------------------------------
# Screenshots/Fotos ins Repo verschieben (mit kollisionssicheren Namen)
# --------------------------------------------------------------------------
function Move-Pics {
    $src = $script:cfg.PicsFolder
    if ([string]::IsNullOrWhiteSpace($src)) { return }   # Feld leer -> Funktion aus
    if (-not (Test-Path $src)) { Write-Log "Bilder-Ordner nicht gefunden - uebersprungen."; return }
    $dst = Join-Path $script:cfg.RepoPath 'pics'
    if (-not (Test-Path $dst)) { New-Item -ItemType Directory -Path $dst -Force | Out-Null }

    $exts = @('.jpg', '.jpeg', '.png')
    $files = Get-ChildItem -Path $src -Recurse -File -ErrorAction SilentlyContinue |
    Where-Object { $exts -contains $_.Extension.ToLowerInvariant() }
    if (-not $files) { Write-Log "Keine neuen Bilder gefunden."; return }

    $safe = ($script:cfg.PlayerName -replace '[^\w\-]', '_')
    if ([string]::IsNullOrWhiteSpace($safe)) { $safe = "Unbekannt" }

    $moved = 0
    foreach ($f in $files) {
        # Eindeutiger Name: Spieler + Aufnahme-Zeit + Originalname (alles bereinigt)
        $stamp = $f.LastWriteTime.ToString("yyyyMMdd-HHmmss")
        $stem = ("{0}_{1}_{2}" -f $safe, $stamp, $f.BaseName) -replace '[^\w\-]', '_'
        $ext = $f.Extension.ToLowerInvariant()
        $target = Join-Path $dst ($stem + $ext)
        $i = 1
        while (Test-Path $target) {
            $target = Join-Path $dst ("{0}_{1}{2}" -f $stem, $i, $ext)
            $i++
        }
        try { Move-Item -LiteralPath $f.FullName -Destination $target -Force; $moved++ }
        catch { Write-Log "Bild konnte nicht verschoben werden: $($f.Name)" }
    }
    Write-Log ("{0} Bild(er) ins Repo verschoben und lokal entfernt." -f $moved)
}

# --------------------------------------------------------------------------
# Spielstaende zwischen Dolphin-Ordner und Repo kopieren
# --------------------------------------------------------------------------
function Get-RepoSaveDir { Join-Path $script:cfg.RepoPath 'save' }

# true = ok/uebersprungen, false = echter Fehler
function Restore-Saves {
    $src = Get-RepoSaveDir
    $dst = $script:cfg.SaveFolder
    if ([string]::IsNullOrWhiteSpace($dst)) { return $true }   # Feld leer -> Funktion aus
    if (-not (Test-Path $src) -or -not (Get-ChildItem -Force $src -ErrorAction SilentlyContinue | Select-Object -First 1)) {
        Write-Log "Noch kein Spielstand im Repo - vorhandener Dolphin-Save bleibt unangetastet."
        return $true
    }
    if (-not (Test-Path $dst)) { New-Item -ItemType Directory -Path $dst -Force | Out-Null }
    Write-Log "Schreibe Spielstand aus dem Repo in den Dolphin-Ordner..."
    # /E = inkl. Unterordner, ueberschreibt; bewusst OHNE Loeschen, damit im
    # Dolphin-Ordner nichts Fremdes geloescht wird.
    $null = robocopy $src $dst /E /NJH /NJS /NDL /NC /NS /NP /R:1 /W:1 2>&1
    if ($LASTEXITCODE -ge 8) { Write-Log "FEHLER beim Zurueckschreiben (robocopy-Code $LASTEXITCODE)."; return $false }
    return $true
}

function Backup-Saves {
    $src = $script:cfg.SaveFolder
    $dst = Get-RepoSaveDir
    if ([string]::IsNullOrWhiteSpace($src)) { return $true }   # Feld leer -> Funktion aus
    if (-not (Test-Path $src) -or -not (Get-ChildItem -Force $src -ErrorAction SilentlyContinue | Select-Object -First 1)) {
        Write-Log "Dolphin-Save-Ordner ist leer/fehlt - nichts zu sichern."
        return $true
    }
    if (-not (Test-Path $dst)) { New-Item -ItemType Directory -Path $dst -Force | Out-Null }
    # /MIR = spiegelt exakt ins repo-eigene 'save/' (dort ist Spiegeln sicher).
    $null = robocopy $src $dst /MIR /NJH /NJS /NDL /NC /NS /NP /R:1 /W:1 2>&1
    if ($LASTEXITCODE -ge 8) { Write-Log "FEHLER beim Sichern (robocopy-Code $LASTEXITCODE)."; return $false }
    return $true
}

# --------------------------------------------------------------------------
# Spielzeit-Erfassung + README-Statistik
# --------------------------------------------------------------------------
function Get-PlaytimePath { Join-Path $script:cfg.RepoPath 'playtime.json' }

function Get-Playtime {
    $p = Get-PlaytimePath
    $h = @{}
    if (Test-Path $p) {
        try {
            $j = Get-Content $p -Raw | ConvertFrom-Json
            foreach ($prop in $j.PSObject.Properties) {
                $v = $prop.Value
                $h[$prop.Name] = @{
                    TotalSeconds  = [double]$v.TotalSeconds
                    Sessions      = [int]$v.Sessions
                    LastPlayedUtc = [string]$v.LastPlayedUtc
                }
            }
        }
        catch {
            Write-Log "WARNUNG: playtime.json ist beschaedigt - die Spielzeit-Statistik kann unvollstaendig sein."
            Write-Log ("  Grund: {0}" -f $_.Exception.Message)
        }
    }
    return $h
}

function Save-Playtime {
    param($h)
    ($h | ConvertTo-Json -Depth 5) | Set-Content -Path (Get-PlaytimePath) -Encoding UTF8
}

function Format-Duration {
    param([double]$sec)
    if ($sec -lt 0) { $sec = 0 }
    $ts = [TimeSpan]::FromSeconds([math]::Round($sec))
    if ($ts.TotalHours -ge 1) { return ("{0}h {1}m" -f [int][math]::Floor($ts.TotalHours), $ts.Minutes) }
    elseif ($ts.TotalMinutes -ge 1) { return ("{0}m {1}s" -f $ts.Minutes, $ts.Seconds) }
    else { return ("{0}s" -f $ts.Seconds) }
}

function Write-Readme {
    param($h)
    if ($null -eq $h) { $h = @{} }
    $lines = @()
    $lines += "# Gemeinsamer Animal-Crossing-Spielstand"
    $lines += ""
    $lines += "Verwaltet mit ``AC-SaveSync.ps1``."
    $lines += ""
    $lines += "## Spielzeiten"
    $lines += ""
    $lines += "| Spieler | Gesamt | Sitzungen | Zuletzt gespielt |"
    $lines += "|---|---|---|---|"
    $total = 0.0
    if ($h.Keys.Count -eq 0) {
        $lines += "| _noch keine Daten_ | - | - | - |"
    }
    else {
        foreach ($name in ($h.Keys | Sort-Object)) {
            $e = $h[$name]
            $total += [double]$e.TotalSeconds
            $last = "-"
            if ($e.LastPlayedUtc) {
                try { $last = [datetimeoffset]::Parse($e.LastPlayedUtc).LocalDateTime.ToString("yyyy-MM-dd HH:mm") }
                catch { $last = "-" }   # unlesbarer Zeitstempel -> Strich in der Tabelle
            }
            $lines += ("| {0} | {1} | {2} | {3} |" -f $name, (Format-Duration $e.TotalSeconds), $e.Sessions, $last)
        }
    }
    $lines += ""
    $lines += ("**Gesamt zusammen:** {0}" -f (Format-Duration $total))

    # Fotos-Galerie (falls Bilder im Repo liegen), neueste zuerst
    $picsDir = Join-Path $script:cfg.RepoPath 'pics'
    if (Test-Path $picsDir) {
        $imgExts = @('.jpg', '.jpeg', '.png')
        $imgs = Get-ChildItem -Path $picsDir -File -ErrorAction SilentlyContinue |
        Where-Object { $imgExts -contains $_.Extension.ToLowerInvariant() } |
        Sort-Object Name -Descending
        if ($imgs -and $imgs.Count -gt 0) {
            $lines += ""
            $lines += ("## Fotos ({0})" -f $imgs.Count)
            $lines += ""
            foreach ($img in $imgs) {
                $lines += ("![{0}](pics/{1})" -f $img.BaseName, $img.Name)
            }
        }
    }

    $lines += ""
    $lines += ("_Zuletzt aktualisiert: {0}_" -f (Get-Date).ToString("yyyy-MM-dd HH:mm"))
    ($lines -join "`r`n") | Set-Content -Path (Join-Path $script:cfg.RepoPath 'README.md') -Encoding UTF8
}

# Rechnet die seit dem letzten Zeitpunkt vergangenen Sekunden dem aktuellen
# Spieler an und aktualisiert playtime.json + README. Mit -EndSession wird
# zusaetzlich der Sitzungszaehler erhoeht.
function Add-Playtime {
    param([switch]$EndSession)
    $now = Get-Date
    $deltaSec = ($now - $script:lastAccounted).TotalSeconds
    if ($deltaSec -lt 0) { $deltaSec = 0 }
    $script:lastAccounted = $now

    $name = $script:cfg.PlayerName
    if ([string]::IsNullOrWhiteSpace($name)) { $name = "Unbekannt" }
    $h = Get-Playtime
    if (-not $h.ContainsKey($name)) {
        $h[$name] = @{ TotalSeconds = 0.0; Sessions = 0; LastPlayedUtc = "" }
    }
    $h[$name].TotalSeconds = [double]$h[$name].TotalSeconds + $deltaSec
    $h[$name].LastPlayedUtc = [datetime]::UtcNow.ToString("o")
    if ($EndSession) { $h[$name].Sessions = [int]$h[$name].Sessions + 1 }
    Save-Playtime $h
    Write-Readme $h
}

# --------------------------------------------------------------------------
# Repo-Einrichtung (gemeinsames Git-Repo erstellen / verbinden / klonen)
# --------------------------------------------------------------------------
function Initialize-Repo {
    Save-ConfigFromUI
    if (-not (Test-Path $script:cfg.RepoPath)) {
        New-Item -ItemType Directory -Path $script:cfg.RepoPath -Force | Out-Null
        Write-Log "Ordner erstellt: $($script:cfg.RepoPath)"
    }
    if (Test-Path (Join-Path $script:cfg.RepoPath '.git')) {
        Write-Log "Ordner ist bereits ein Git-Repo."
    }
    else {
        $r = Invoke-Git @('init')
        Write-Log "git init: $($r.Text)"
    }
    $ga = Join-Path $script:cfg.RepoPath '.gitattributes'
    if (-not (Test-Path $ga)) {
        @"
# Spielstaende sind Binaerdateien: keine Zeilenende-Umwandlung, kein Merge
save/** -text -diff
pics/** -text -diff
*.bin -text -diff
*.raw -text -diff
*.dat -text -diff
*.sav -text -diff
"@ | Set-Content -Path $ga -Encoding UTF8
    }
    Write-Readme (Get-Playtime)
    Invoke-Git @('add', '-A') | Out-Null
    if (-not (Test-Staged)) {
        Write-Log "Nichts Neues zu committen (schon eingerichtet)."
    }
    else {
        $c = Invoke-Git @('commit', '-m', 'Repo-Setup durch AC-SaveSync')
        if ($c.Code -eq 0) {
            Write-Log "Erster Commit erstellt."
        }
        else {
            Write-GitProblem "Das Repo ist noch nicht startklar - Speichern fehlgeschlagen." $c
        }
    }
    Invoke-Git @('branch', '-M', $script:cfg.Branch) | Out-Null
    Write-Log "Lokales Repo bereit (Branch: $($script:cfg.Branch))."
}

function Connect-Remote {
    param([string]$url)
    Save-ConfigFromUI
    if ([string]::IsNullOrWhiteSpace($url)) { Write-Log "Bitte im Fenster oben die Remote-URL eintragen."; return }
    if (-not (Test-Path (Join-Path $script:cfg.RepoPath '.git'))) {
        Write-Log "Erst Schritt 1 (Lokales Repo anlegen) ausfuehren."; return
    }
    $r = Invoke-Git @('remote')
    if ($r.Text -match '(^|\r?\n)origin(\r?\n|$)') {
        Invoke-Git @('remote', 'set-url', 'origin', $url) | Out-Null
        Write-Log "origin aktualisiert."
    }
    else {
        Invoke-Git @('remote', 'add', 'origin', $url) | Out-Null
        Write-Log "origin hinzugefuegt."
    }
    $p = Invoke-Git @('push', '-u', 'origin', $script:cfg.Branch)
    if ($p.Code -eq 0) { Write-Log "Hochgeladen. Das Repo ist jetzt startklar - der andere kann es nun klonen." }
    else { Write-GitProblem "Hochladen fehlgeschlagen." $p }
}

function Copy-Repo {
    param([string]$url)
    Save-ConfigFromUI
    if ([string]::IsNullOrWhiteSpace($url)) { Write-Log "Bitte im Fenster oben die Remote-URL eintragen."; return }
    $target = $script:cfg.RepoPath
    if (Test-Path (Join-Path $target '.git')) { Write-Log "Zielordner ist bereits ein Repo - Klonen nicht noetig."; return }
    if ((Test-Path $target) -and (Get-ChildItem -Force $target | Select-Object -First 1)) {
        Write-Log "Zielordner ist nicht leer. Bitte einen leeren/neuen Ordner als RepoPath waehlen."; return
    }
    Write-Log "Klone Repo..."
    $out = & git clone $url $target 2>&1
    $text = ConvertTo-GitText $out
    if (-not (Test-Path (Join-Path $target '.git'))) {
        Write-GitProblem "Das gemeinsame Repo konnte nicht geholt werden." ([pscustomobject]@{ Text = $text })
        return
    }

    # Nach dem Klonen sicherstellen, dass der eingestellte Branch auch wirklich
    # ausgecheckt ist. Zeigt der Server auf einen anders benannten Standard-
    # Branch (z. B. 'master' statt 'main'), ist der Ordner sonst LEER - und das
    # faellt sonst erst beim Spielen auf, wenn der Spielstand fehlt.
    $cur = Invoke-Git @('rev-parse', '--abbrev-ref', 'HEAD')
    if ($cur.Code -ne 0 -or $cur.Text -ne $script:cfg.Branch) {
        $co = Invoke-Git @('checkout', '-B', $script:cfg.Branch, "origin/$($script:cfg.Branch)")
        if ($co.Code -ne 0) {
            Write-GitProblem ("Der Ordner wurde geholt, aber der Branch '{0}' konnte nicht ausgecheckt werden - er ist noch leer." -f $script:cfg.Branch) $co
            Write-Log "  Tipp: Pruefe unter 'Erweitert...', ob der Branch stimmt (meist 'main')."
            return
        }
        Write-Log ("Branch '{0}' ausgecheckt." -f $script:cfg.Branch)
    }
    Write-Log "Klonen erfolgreich. Du kannst jetzt spielen."
}

function New-RemoteWithGh {
    param([string]$name)
    Save-ConfigFromUI
    if ([string]::IsNullOrWhiteSpace($name)) { Write-Log "Bitte einen Repo-Namen eingeben."; return }
    $gh = Get-Command gh -ErrorAction SilentlyContinue
    if (-not $gh) {
        Write-Log "GitHub CLI (gh) nicht gefunden. Erstelle das leere Repo auf github.com und nutze dann 'Verbinden & hochladen'."
        return
    }
    Initialize-Repo
    Write-Log "Erstelle privates GitHub-Repo '$name' und lade hoch..."
    $out = & gh repo create $name --private --source $script:cfg.RepoPath --remote origin --push 2>&1
    Write-Log ("gh: " + (($out | Out-String).Trim()))
}

# --------------------------------------------------------------------------
# Erststart-Assistent
# --------------------------------------------------------------------------
# Fuehrt beim allerersten Start in vier Schritten durch das Noetigste, statt
# neun leere Felder hinzustellen. Wie im Rest des Programms bewusst OHNE
# GetNewClosure(): die Knopf-Handler merken sich ihre Felder in $script:-Variablen.

function Update-WizStep {
    for ($i = 0; $i -lt $script:wizPanels.Count; $i++) {
        $script:wizPanels[$i].Visible = ($i -eq $script:wizStep)
    }
    $script:wizBack.Enabled = ($script:wizStep -gt 0)
    $script:wizNext.Text = if ($script:wizStep -ge $script:wizPanels.Count - 1) { "Fertig" } else { "Weiter >" }
    $script:wizKopf.Text = $script:wizTitel[$script:wizStep]
}

function Invoke-WizNext {
    if ($script:wizStep -ge $script:wizPanels.Count - 1) {
        $script:wizDlg.DialogResult = 'OK'
        $script:wizDlg.Close()
        return
    }
    $script:wizStep++
    Update-WizStep
}

function Invoke-WizBack {
    if ($script:wizStep -gt 0) { $script:wizStep-- }
    Update-WizStep
}

function Show-FirstRunWizard {
    $dlg = New-Object Windows.Forms.Form
    $script:wizDlg = $dlg
    $dlg.Text = "Willkommen - Einrichtung in 4 Schritten"
    $dlg.Size = New-Object Drawing.Size(640, 470)
    $dlg.StartPosition = "CenterScreen"
    $dlg.FormBorderStyle = 'FixedDialog'
    $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
    if ($script:appIcon) { $dlg.Icon = $script:appIcon }

    $script:wizKopf = New-Object Windows.Forms.Label
    $script:wizKopf.Location = New-Object Drawing.Point(18, 14)
    $script:wizKopf.Size = New-Object Drawing.Size(590, 26)
    $script:wizKopf.Font = New-Object Drawing.Font("Segoe UI", 12, [Drawing.FontStyle]::Bold)
    $dlg.Controls.Add($script:wizKopf)

    function NeuPanel {
        $p = New-Object Windows.Forms.Panel
        $p.Location = New-Object Drawing.Point(18, 48)
        $p.Size = New-Object Drawing.Size(596, 320)
        $p.Visible = $false
        $dlg.Controls.Add($p)
        return $p
    }
    function NeuText($panel, $text, $y, $hoehe = 60) {
        $l = New-Object Windows.Forms.Label
        $l.Text = $text
        $l.Location = New-Object Drawing.Point(2, $y)
        $l.Size = New-Object Drawing.Size(590, $hoehe)
        $panel.Controls.Add($l)
        return $l
    }
    function NeuFeld($panel, $beschriftung, $wert, $y) {
        $l = New-Object Windows.Forms.Label
        $l.Text = $beschriftung
        $l.Location = New-Object Drawing.Point(2, $y)
        $l.Size = New-Object Drawing.Size(150, 22)
        $l.TextAlign = 'MiddleLeft'
        $panel.Controls.Add($l)
        $t = New-Object Windows.Forms.TextBox
        $t.Text = "$wert"
        $t.Location = New-Object Drawing.Point(156, $y)
        $t.Size = New-Object Drawing.Size(370, 22)
        $panel.Controls.Add($t)
        return $t
    }

    # ---- Schritt 1: Willkommen + Git-Pruefung -----------------------------
    $p1 = NeuPanel
    NeuText $p1 ("Dieses Programm sorgt dafuer, dass ihr euch beim Spielen nicht in die" + [Environment]::NewLine +
        "Quere kommt: Es holt vor dem Spielen den neuesten Spielstand, meldet euch" + [Environment]::NewLine +
        "als 'spielt gerade' an und laedt danach alles wieder hoch." + [Environment]::NewLine + [Environment]::NewLine +
        "Die Einrichtung dauert zwei Minuten. Alles laesst sich spaeter aendern.") 6 110 | Out-Null

    $gitOk = ((Invoke-GitRaw @('--version')).Code -eq 0)
    $lg = NeuText $p1 "" 128 44
    if ($gitOk) {
        $lg.Text = "Git ist installiert - alles bereit."
        $lg.ForeColor = [Drawing.Color]::FromArgb(0, 110, 0)
    }
    else {
        $lg.Text = ("Git fehlt. Ohne Git kann nichts ausgetauscht werden." + [Environment]::NewLine +
            "Bitte herunterladen, installieren und das Programm danach neu starten.")
        $lg.ForeColor = [Drawing.Color]::FromArgb(170, 0, 0)
        $bg = New-Object Windows.Forms.Button
        $bg.Text = "Git-Download oeffnen"
        $bg.Location = New-Object Drawing.Point(2, 178)
